def choose_move(observation):
    wx = observation.get("self_position", {}).get("x", 0)
    wy = observation.get("self_position", {}).get("y", 0)
    ox = observation.get("opponent_position", {}).get("x", 0)
    oy = observation.get("opponent_position", {}).get("y", 0)

    # Prefer moving away from opponent if possible, else towards any resource, else stay.
    dx = 0
    dy = 0

    # Try simple rule: step away from opponent
    if ox > wx:
        dx = -1
    elif ox < wx:
        dx = 1
    if oy > wy:
        dy = -1
    elif oy < wy:
        dy = 1

    # If this would land outside grid, clamp to stay or adjust to stay safe
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    nx = wx + dx
    ny = wy + dy
    if gw:
        if nx < 0 or nx >= gw:
            dx = 0
    if gh:
        if ny < 0 or ny >= gh:
            dy = 0

    # If both zero move not allowed in some environments, check for a nearby resource
    if dx == 0 and dy == 0:
        resources = observation.get("resources", [])
        best = None
        for r in resources:
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
                continue
            ddx = 1 if rx > wx else (-1 if rx < wx else 0)
            ddy = 1 if ry > wy else (-1 if ry < wy else 0)
            dist = abs(rx - wx) + abs(ry - wy)
            if best is None or dist < best[0]:
                best = (dist, ddx, ddy)
        if best is not None:
            dx, dy = best[1], best[2]

    return [dx, dy]
